window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-56b7309e20a4adfb"]={"versions": [{"id": "FIG-56b7309e20a4adfb", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Paketdiagramm / High-Level Architektur-Strukturdiagramm der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Definition der Top-Level-Architektur der Speicherdomäne (<em>Storage Domain</em>) innerhalb der Adaptive Platform Foundation gemäß <code>AUTOSAR_EXP_SWArchitecture</code> (Kapitel 9, Release R20-11).\n</li><li><strong>Funktionale Einordnung:</strong> Kapselt die gesamte Funktionalität zur persistenten, nicht-flüchtigen Datenspeicherung in einem einzigen, zentralen Functional Cluster (<strong>Persistency</strong>, C++-Namespace <code>ara::per</code>). Im Gegensatz zur AUTOSAR Classic Platform (wo Speicher in NvM, MemIf, Fee/Ea, Fls/Eep aufgeteilt ist) abstrahiert dieser Functional Cluster die Persistierung monolithisch gegenüber den Adaptive Applications (AA) über dem zugrundeliegenden POSIX-Betriebssystem.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Functional Cluster <code>Persistency</code>:</strong> Dargestellt als UML-Standardpaket (grüne Farbkennzeichnung gemäß AUTOSAR-Konvention für funktionale Standard-Cluster der Adaptive Platform).\n</li></ul>\n</li><li><strong>Kapselung &amp; Sub-Bausteine (Building Blocks nach R20-11 Spezifikation):</strong>\n<ul class=\"fig-list\"><li><strong>Key-Value Storage (KVS):</strong> Bietet typisierten Lese- und Schreibzugriff auf strukturierte Datenobjekte (<code>ara::per::KeyValueStorage</code>).\n</li><li><strong>File Storage (FS):</strong> Bietet unstrukturierten, stream-basierten Dateizugriff (<code>ara::per::FileStorage</code>).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Modell-Bindung:</strong>\n<ul class=\"fig-list\"><li><strong>Applikations-Interface (<code>ara::per</code>):</strong> C++14/C++17-Klassen und -Methoden, bereitgestellt im User-Space der Adaptive Application.\n</li><li><strong>Meta-Model / Manifest-Entitäten:</strong> Bindung über das ARXML-Modell (<code>PersistencyPortPrototype</code>, <code>PersistencyPortToPortAllocation</code>, <code>PersistencyDeployment</code>).\n</li><li><strong>Betriebssystem-Abstraktion:</strong> Interne Bindung an POSIX-Dateisystemaufrufe (POSIX PSE52/PSE53-Profil).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammdynamik:</strong> Reines statisches Paket-/Strukturdiagramm; kein Sequenz- oder Zustandsablauf im Bild abgebildet.\n</li><li><strong>Laufzeitverhalten des Clusters (<code>ara::per</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Initialisierung:</strong> Automatisch über den Runtime-Kontext der Adaptive Platform (<code>ara::core::Initialize()</code>).\n</li><li><strong>Instanziierung &amp; Zugriff:</strong>\n<ul class=\"fig-list\"><li>Instanziierung erfolgt über symbolische Modell-Referenzen: <code>ara::per::OpenKeyValueStorage(ara::core::InstanceSpecifier)</code> bzw. <code>ara::per::OpenFileStorage(...)</code>.\n</li></ul>\n</li><li><strong>Persistierung &amp; Synchronisation:</strong>\n<ul class=\"fig-list\"><li>Schreibvorgänge puffern Daten; die physische Persistierung auf dem Speichermedium erfordert den synchronen Aufruf von <code>SyncToStorage()</code>.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Rückgabe über <code>ara::core::Result&lt;T, ara::per::PerErrc&gt;</code> (keine C++-Exceptions gemäß AUTOSAR AP Spezifikation).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Keine Classic-Platform-Treiberarchitektur:</strong>\n<ul class=\"fig-list\"><li>Es existieren keine konfigurierbaren BSW-Treiber wie <code>NvM</code> oder <code>Fee</code>. Die Implementierung des Functional Clusters obliegt dem Adaptive-Platform-Stack-Hersteller (i. d. R. implementiert über JSON/BSON, SQLite oder flache Binärdateien auf Flash-/eMMC-Partitionen).\n</li></ul>\n</li><li><strong>Modell- &amp; Manifest-Pflicht:</strong>\n<ul class=\"fig-list\"><li>Applikationen dürfen keine direkten POSIX-Dateipfade verwenden. Zugriff ist ausschließlich über deklarierte Ports (<code>PersistencyPortPrototype</code>) im Adaptive Application Manifest erlaubt. Der Stack-Integrator weist diesen Ports über Deployment-Deskriptoren physische Speicherorte und Quotas zu.\n</li></ul>\n</li><li><strong>Datenintegrität &amp; Redundanz:</strong>\n<ul class=\"fig-list\"><li>Der Cluster garantiert über interne Integritätsmechanismen (z. B. Checksummen, MBN-Redundanz) Ausfallsicherheit bei Spannungsabfall (<em>Power-Loss Consistency</em>).\n</li></ul>\n</li><li><strong>Prozessisolation &amp; Security:</strong>\n<ul class=\"fig-list\"><li>Jeder Zugriff wird über POSIX-UIDs und ggf. Identity and Access Management (<code>ara::iam</code>) gegen unbefugten Zugriff anderer Prozesse/Container isoliert.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4f9b8edeacf743e8", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Paketdiagramm / High-Level Architektur-Strukturdiagramm der AUTOSAR Adaptive Platform (AP).\n</li><li><strong>Technischer Zweck:</strong> Definition der Top-Level-Architektur der Speicherdomäne (<em>Storage Domain</em>) innerhalb der Adaptive Platform Foundation gemäß <code>AUTOSAR_EXP_SWArchitecture</code> (Kapitel 9, Release R20-11).\n</li><li><strong>Funktionale Einordnung:</strong> Kapselt die gesamte Funktionalität zur persistenten, nicht-flüchtigen Datenspeicherung in einem einzigen, zentralen Functional Cluster (<strong>Persistency</strong>, C++-Namespace <code>ara::per</code>). Im Gegensatz zur AUTOSAR Classic Platform (wo Speicher in NvM, MemIf, Fee/Ea, Fls/Eep aufgeteilt ist) abstrahiert dieser Functional Cluster die Persistierung monolithisch gegenüber den Adaptive Applications (AA) über dem zugrundeliegenden POSIX-Betriebssystem.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dargestellte Entitäten:</strong>\n<ul class=\"fig-list\"><li><strong>Functional Cluster <code>Persistency</code>:</strong> Dargestellt als UML-Standardpaket (grüne Farbkennzeichnung gemäß AUTOSAR-Konvention für funktionale Standard-Cluster der Adaptive Platform).\n</li></ul>\n</li><li><strong>Kapselung &amp; Sub-Bausteine (Building Blocks nach R20-11 Spezifikation):</strong>\n<ul class=\"fig-list\"><li><strong>Key-Value Storage (KVS):</strong> Bietet typisierten Lese- und Schreibzugriff auf strukturierte Datenobjekte (<code>ara::per::KeyValueStorage</code>).\n</li><li><strong>File Storage (FS):</strong> Bietet unstrukturierten, stream-basierten Dateizugriff (<code>ara::per::FileStorage</code>).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Modell-Bindung:</strong>\n<ul class=\"fig-list\"><li><strong>Applikations-Interface (<code>ara::per</code>):</strong> C++14/C++17-Klassen und -Methoden, bereitgestellt im User-Space der Adaptive Application.\n</li><li><strong>Meta-Model / Manifest-Entitäten:</strong> Bindung über das ARXML-Modell (<code>PersistencyPortPrototype</code>, <code>PersistencyPortToPortAllocation</code>, <code>PersistencyDeployment</code>).\n</li><li><strong>Betriebssystem-Abstraktion:</strong> Interne Bindung an POSIX-Dateisystemaufrufe (POSIX PSE52/PSE53-Profil).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammdynamik:</strong> Reines statisches Paket-/Strukturdiagramm; kein Sequenz- oder Zustandsablauf im Bild abgebildet.\n</li><li><strong>Laufzeitverhalten des Clusters (<code>ara::per</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Initialisierung:</strong> Automatisch über den Runtime-Kontext der Adaptive Platform (<code>ara::core::Initialize()</code>).\n</li><li><strong>Instanziierung &amp; Zugriff:</strong>\n<ul class=\"fig-list\"><li>Instanziierung erfolgt über symbolische Modell-Referenzen: <code>ara::per::OpenKeyValueStorage(ara::core::InstanceSpecifier)</code> bzw. <code>ara::per::OpenFileStorage(...)</code>.\n</li></ul>\n</li><li><strong>Persistierung &amp; Synchronisation:</strong>\n<ul class=\"fig-list\"><li>Schreibvorgänge puffern Daten; die physische Persistierung auf dem Speichermedium erfordert den synchronen Aufruf von <code>SyncToStorage()</code>.\n</li></ul>\n</li><li><strong>Fehlerbehandlung:</strong> Rückgabe über <code>ara::core::Result&lt;T, ara::per::PerErrc&gt;</code> (keine C++-Exceptions gemäß AUTOSAR AP Spezifikation).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Keine Classic-Platform-Treiberarchitektur:</strong>\n<ul class=\"fig-list\"><li>Es existieren keine konfigurierbaren BSW-Treiber wie <code>NvM</code> oder <code>Fee</code>. Die Implementierung des Functional Clusters obliegt dem Adaptive-Platform-Stack-Hersteller (i. d. R. implementiert über JSON/BSON, SQLite oder flache Binärdateien auf Flash-/eMMC-Partitionen).\n</li></ul>\n</li><li><strong>Modell- &amp; Manifest-Pflicht:</strong>\n<ul class=\"fig-list\"><li>Applikationen dürfen keine direkten POSIX-Dateipfade verwenden. Zugriff ist ausschließlich über deklarierte Ports (<code>PersistencyPortPrototype</code>) im Adaptive Application Manifest erlaubt. Der Stack-Integrator weist diesen Ports über Deployment-Deskriptoren physische Speicherorte und Quotas zu.\n</li></ul>\n</li><li><strong>Datenintegrität &amp; Redundanz:</strong>\n<ul class=\"fig-list\"><li>Der Cluster garantiert über interne Integritätsmechanismen (z. B. Checksummen, MBN-Redundanz) Ausfallsicherheit bei Spannungsabfall (<em>Power-Loss Consistency</em>).\n</li></ul>\n</li><li><strong>Prozessisolation &amp; Security:</strong>\n<ul class=\"fig-list\"><li>Jeder Zugriff wird über POSIX-UIDs und ggf. Identity and Access Management (<code>ara::iam</code>) gegen unbefugten Zugriff anderer Prozesse/Container isoliert.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-56b7309e20a4adfb", "to": "FIG-4f9b8edeacf743e8", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
